-- Mission PC3: rich indoor plant collection (data-only migration).
--
-- Adds 120 potted-plant listings under the 'plants' top across
-- six subcategories (indoor, flowering, succulents, herbs,
-- medicinal, aromatic), a new 'medicinal' subcategory with
-- 6-language names, renames 'herbs' to "Culinary herbs" now that
-- a dedicated 'medicinal' sub exists, and links the five
-- pre-existing plant products into the category tree.
--
-- Everything is idempotent: fixed primary keys, ON CONFLICT DO
-- NOTHING on inserts, and guarded UPDATEs that only touch rows
-- still in their pre-tree state (categoryId NULL). Re-running on
-- a partially applied database is safe. All rows belong to the
-- verified nursery slug 'green-leaf' (Bengaluru); if that nursery
-- is absent the product INSERT simply matches no rows.

-- 1) 'herbs' sub now means culinary herbs only.
UPDATE "Category" SET names = '{"en":"Culinary herbs","hi":"रसोई जड़ी-बूटियाँ","kn":"ಅಡುಗೆ ಮೂಲಿಕೆಗಳು","mr":"स्वयंपाक औषधी","ta":"சமையல் மூலிகைகள்","te":"వంట మూలికలు"}'::jsonb WHERE slug = 'herbs';

-- 2) New 'medicinal' sub under the 'plants' top (sortOrder 45 sits
--    between herbs 40 and aromatic 50). gstRate NULL inherits the
--    top's 5 percent.
INSERT INTO "Category" (id, slug, "parentId", names, emoji, "gstRate", "legacyKey", "sortOrder", active, "createdAt")
SELECT 'plt_cat_medicinal', 'medicinal', p.id, '{"en":"Medicinal plants","hi":"औषधीय पौधे","kn":"ಔಷಧೀಯ ಗಿಡಗಳು","mr":"औषधी वनस्पती","ta":"மருத்துவ செடிகள்","te":"ఔషధీయ మొక్కలు"}'::jsonb, NULL, NULL, NULL, 45, true, now()
FROM "Category" p
WHERE p.slug = 'plants' AND p."parentId" IS NULL
ON CONFLICT (slug) DO NOTHING;

-- 3) Fold the five legacy plant products into the tree (guarded:
--    only rows with no categoryId yet, so admin edits always win).
UPDATE "Product" SET "categoryId" = (SELECT id FROM "Category" WHERE slug = 'succulents'), "subCategory" = 'succulents'
WHERE "nameEn" IN ('Jade Plant') AND category = 'plants' AND "categoryId" IS NULL;

UPDATE "Product" SET "categoryId" = (SELECT id FROM "Category" WHERE slug = 'herbs'), "subCategory" = 'herbs'
WHERE "nameEn" IN ('Curry Leaf Plant') AND category = 'plants' AND "categoryId" IS NULL;

UPDATE "Product" SET "categoryId" = (SELECT id FROM "Category" WHERE slug = 'aromatic'), "subCategory" = 'aromatic'
WHERE "nameEn" IN ('Lemongrass', 'Jasmine') AND category = 'plants' AND "categoryId" IS NULL;

-- 4) The 120 new listings. id is deterministic (plt_<slug>) so the
--    whole statement is re-runnable; categoryId resolves via the
--    subcategory slug so no production cuids are hard-coded.
INSERT INTO "Product" (id, "nurseryId", category, "categoryId", "nameEn", names, botanical, badges, care, provenance, "priceMin", mrp, stock, hidden, "subCategory", image)
